CREATE INDEX IF NOT EXISTS ix_events_end_time ON events (end_time);
CREATE INDEX IF NOT EXISTS ix_events_event_type ON events (event_type);
CREATE INDEX IF NOT EXISTS ix_events_venue_id ON events (venue_id);
